package com.nigson.experience.engagement;
import com.nigson.experience.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.*;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import static org.assertj.core.api.Assertions.*;
class EngagementPersistenceTest {
 private JdbcTemplate jdbc;private EngagementService service;private DataSourceTransactionManager manager;private Clock clock=Clock.systemUTC();private UUID party=UUID.randomUUID();private UUID marketRef=UUID.randomUUID();
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"engagement PostgreSQL acceptance uses scripts/engagement/verify.py");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();service=new EngagementService(jdbc,new PlatformStore(jdbc,manager,clock,metrics),new AuditWriter(jdbc,clock,metrics),(p,l,product)->p.equals(party)&&l.toString().startsWith("2"),new EngagementService.MarketValidator(){public boolean active(UUID m){return true;}public UUID resolve(String code){return code.equals("NG")?marketRef:null;}},clock);}
 private PrivateWorkload.Proof proof(String api,String role,String scope){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();var actor=new ActorAssertion.Actor(party,"https://identity.synthetic.invalid","synthetic-user",null,Set.of(role),Set.of(scope),null);return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,actor);}
 @Test void purchaseProofPrecedesWritesAndModerationIsVersionedAuditedAndOutboxed(){long reviewsBefore=jdbc.queryForObject("SELECT count(*) FROM experience.review",Long.class);UUID product=UUID.randomUUID(),line=UUID.fromString("22222222-2222-4222-8222-222222222222");var customer=proof("API-096","CUSTOMER","reviews.create_WITH_SIGNED_CUSTOMER");var fake=new EngagementValues.ReviewInput("PRODUCT",product,UUID.fromString("11111111-1111-4111-8111-111111111111"),5,"Title","Body");assertThatThrownBy(()->service.create(customer,fake,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(e->((Problem.Failure)e).code).isEqualTo(ProblemCode.ENGAGEMENT_RULE_VIOLATION);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.review",Long.class)).isEqualTo(reviewsBefore);var input=new EngagementValues.ReviewInput("PRODUCT",product,line,5,"Good","Verified review");String key=UUID.randomUUID().toString();var first=service.create(customer,input,key,UUID.randomUUID());assertThat(service.create(customer,input,key,UUID.randomUUID())).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.review WHERE id=? AND state='PENDING' AND verified_purchase",Long.class,first.id())).isEqualTo(1);assertThat(service.publicReviews(product,"PRODUCT",0,10,"publishedAt,desc").totalElements()).isZero();var denied=proof("API-098","SALES","reviews.moderate_WITH_SIGNED_ACTOR");assertThatThrownBy(()->service.moderate(denied,first.id(),new EngagementValues.Moderation("PUBLISH","Reviewed and accepted"),0,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(e->((Problem.Failure)e).code).isEqualTo(ProblemCode.ACCESS_DENIED);var publisher=proof("API-098","CONTENT_PUBLISHER","reviews.moderate_WITH_SIGNED_ACTOR");String moderationKey=UUID.randomUUID().toString();var published=service.moderate(publisher,first.id(),new EngagementValues.Moderation("PUBLISH","Reviewed and accepted"),0,moderationKey,UUID.randomUUID());assertThat(service.moderate(publisher,first.id(),new EngagementValues.Moderation("PUBLISH","Reviewed and accepted"),0,moderationKey,UUID.randomUUID())).isEqualTo(published);assertThat(published.version()).isEqualTo(1);assertThatThrownBy(()->service.moderate(publisher,first.id(),new EngagementValues.Moderation("WITHDRAW","Customer requested removal"),0,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(e->((Problem.Failure)e).code).isEqualTo(ProblemCode.VERSION_MISMATCH);var publicPage=service.publicReviews(product,"PRODUCT",0,10,"publishedAt,desc");assertThat(publicPage.totalElements()).isEqualTo(1);assertThat(publicPage.items().getFirst().displayName()).isEqualTo("Nigson customer");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='review.published.v1'",Long.class,first.id())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE resource_type='REVIEW' AND resource_id=?",Long.class,first.id())).isEqualTo(2);}
 @Test void testimonialsRejectPurchaseIdentifiersAndCampaignsAreDisplayOnlyAndMarketBound(){long campaignsBefore=jdbc.queryForObject("SELECT count(*) FROM experience.campaign",Long.class);var customer=proof("API-096","CUSTOMER","reviews.create_WITH_SIGNED_CUSTOMER");var testimonial=service.create(customer,new EngagementValues.ReviewInput("TESTIMONIAL",null,null,null,null,"A general testimonial"),UUID.randomUUID().toString(),UUID.randomUUID());assertThat(testimonial.verifiedPurchase()).isFalse();UUID market=marketRef;Instant now=clock.instant();var sales=proof("API-108","SALES","campaigns.write_WITH_SIGNED_ACTOR");var input=new EngagementValues.CampaignInput("WELCOME","Welcome",market,null,EventCodec.JSON.readTree("{\"headline\":\"Welcome\"}"),now.minusSeconds(30),now.plusSeconds(600),true);String key=UUID.randomUUID().toString();var campaign=service.createCampaign(sales,input,key,UUID.randomUUID());assertThat(service.createCampaign(sales,input,key,UUID.randomUUID())).isEqualTo(campaign);assertThat(service.publicCampaigns("NG")).extracting(EngagementValues.PublicCampaign::id).contains(campaign.id());var unvalidated=new EngagementValues.CampaignInput("BADRULE","Rule",market,UUID.randomUUID(),input.displayConfig(),input.startsAt(),input.endsAt(),true);assertThatThrownBy(()->service.createCampaign(sales,unvalidated,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.campaign",Long.class)).isEqualTo(campaignsBefore+1);}
}
